import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import seaborn as sns
import base64
from io import BytesIO
import os

# Configuration
plt.style.use('seaborn-v0_8-whitegrid')
COLORS = {
    'primary': '#0F172A',
    'secondary': '#3B82F6',
    'accent': '#10B981',
    'danger': '#EF4444',
    'muted': '#64748B'
}

def to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

# Read data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%m/%d/%Y')
df = df.sort_values('Date').reset_index(drop=True)

# Calculate Daily Returns
df['Daily_Return'] = df['Close'].pct_change()

# Calculate Drawdown
df['Rolling_Max'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['Rolling_Max']) / df['Rolling_Max']

# Volatility (Rolling 252-day annualized)
df['Rolling_Volatility'] = df['Daily_Return'].rolling(window=252).std() * np.sqrt(252)

# --- KPIs ---
start_price = df['Close'].iloc[0]
end_price = df['Close'].iloc[-1]
years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25

cumulative_return = ((end_price / start_price) - 1) * 100
cagr = ((end_price / start_price) ** (1 / years) - 1) * 100
max_drawdown = df['Drawdown'].min() * 100
avg_volume = df['Volume'].mean()
annualized_volatility = df['Daily_Return'].std() * np.sqrt(252) * 100

# Annual Performance
df['Year'] = df['Date'].dt.year
annual_prices = df.groupby('Year')['Close'].agg(['first', 'last'])
annual_returns = ((annual_prices['last'] - annual_prices['first']) / annual_prices['first']) * 100

best_year = annual_returns.idxmax()
best_year_return = annual_returns.max()
worst_year = annual_returns.idxmin()
worst_year_return = annual_returns.min()

# Decade Breakdown
df['Decade'] = (df['Year'] // 10) * 10
decade_prices = df.groupby('Decade')['Close'].agg(['first', 'last'])
decade_returns = ((decade_prices['last'] - decade_prices['first']) / decade_prices['first']) * 100

# --- Charts ---
# 1. Price Trend
fig, ax = plt.subplots(figsize=(12, 6))
ax.plot(df['Date'], df['Close'], color=COLORS['primary'], linewidth=1.5, label='NKE Close Price')
ax.plot(df['Date'], df['Close'].rolling(200).mean(), color=COLORS['secondary'], linewidth=1.5, label='200-Day SMA', alpha=0.8)
ax.set_title('Nike Long-Term Price Trend (2000-2026)', fontsize=16, fontweight='bold', pad=15)
ax.set_ylabel('Price (USD)', fontsize=12)
ax.legend(loc='upper left', frameon=True)
ax.grid(True, alpha=0.3)
ax.yaxis.set_major_formatter('${x:1.0f}')
plt.tight_layout()
price_chart = to_base64(fig)

# 2. Drawdown Chart
fig, ax = plt.subplots(figsize=(12, 4))
ax.fill_between(df['Date'], df['Drawdown'] * 100, 0, color=COLORS['danger'], alpha=0.3)
ax.plot(df['Date'], df['Drawdown'] * 100, color=COLORS['danger'], linewidth=1)
ax.set_title('Historical Drawdowns (Peak-to-Trough Decline)', fontsize=14, fontweight='bold', pad=15)
ax.set_ylabel('Drawdown (%)', fontsize=12)
ax.grid(True, alpha=0.3)
ax.yaxis.set_major_formatter('{x:1.0f}%')
plt.tight_layout()
drawdown_chart = to_base64(fig)

# 3. Volatility Chart
fig, ax = plt.subplots(figsize=(12, 4))
ax.plot(df['Date'], df['Rolling_Volatility'] * 100, color=COLORS['muted'], linewidth=1.5)
ax.set_title('Rolling 1-Year Annualized Volatility', fontsize=14, fontweight='bold', pad=15)
ax.set_ylabel('Volatility (%)', fontsize=12)
ax.grid(True, alpha=0.3)
ax.yaxis.set_major_formatter('{x:1.0f}%')
avg_vol = df['Rolling_Volatility'].mean() * 100
ax.axhline(avg_vol, color=COLORS['secondary'], linestyle='--', alpha=0.8, label=f'Avg Volatility ({avg_vol:.1f}%)')
ax.legend(loc='upper right', frameon=True)
plt.tight_layout()
volatility_chart = to_base64(fig)

# 4. Volume Chart
monthly_vol = df.set_index('Date').resample('ME')['Volume'].mean().reset_index()
fig, ax = plt.subplots(figsize=(12, 4))
ax.bar(monthly_vol['Date'], monthly_vol['Volume'] / 1e6, width=25, color=COLORS['secondary'], alpha=0.7)
ax.set_title('Average Daily Trading Volume Over Time', fontsize=14, fontweight='bold', pad=15)
ax.set_ylabel('Volume (Millions)', fontsize=12)
ax.grid(True, alpha=0.3, axis='y')
plt.tight_layout()
volume_chart = to_base64(fig)

# 5. Annual Returns Chart
fig, ax = plt.subplots(figsize=(12, 5))
colors = [COLORS['accent'] if val > 0 else COLORS['danger'] for val in annual_returns]
bars = ax.bar(annual_returns.index, annual_returns, color=colors, alpha=0.85)
ax.set_title('Annual Performance (Year-to-Year Returns)', fontsize=14, fontweight='bold', pad=15)
ax.set_ylabel('Return (%)', fontsize=12)
ax.grid(True, alpha=0.3, axis='y')
ax.yaxis.set_major_formatter('{x:1.0f}%')
ax.set_xticks(annual_returns.index)
ax.set_xticklabels(annual_returns.index, rotation=45)
for bar in bars:
    height = bar.get_height()
    label_y = height + 2 if height >= 0 else height - 6
    ax.text(bar.get_x() + bar.get_width()/2., label_y,
            f'{height:.0f}%',
            ha='center', va='bottom' if height >=0 else 'top', fontsize=9, color=COLORS['primary'], fontweight='bold')
plt.tight_layout()
annual_returns_chart = to_base64(fig)

